<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Rui Silva — Career Cockpit</title>
<style>
  :root {
    --bg: #f8f6f2;
    --surface: #ffffff;
    --ink: #1a1a1a;
    --ink-soft: #4a4a4a;
    --ink-faint: #8a8a8a;
    --accent: #b85c38;
    --accent-soft: #f4e6df;
    --line: #e8e4dc;
    --good: #2d6a4f;
    --good-soft: #d8f3dc;
    --warn: #b7791f;
    --warn-soft: #fef3c7;
    --bad: #9b2226;
    --bad-soft: #fde8e8;
    --sidebar-w: 200px;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "Source Sans Pro", sans-serif;
    background: var(--bg); color: var(--ink); line-height: 1.5;
    display: flex; min-height: 100vh; -webkit-font-smoothing: antialiased;
  }
  /* SIDEBAR */
  .sidebar {
    width: var(--sidebar-w); background: var(--surface); border-right: 1px solid var(--line);
    display: flex; flex-direction: column; flex-shrink: 0; height: 100vh; position: sticky; top: 0;
  }
  .sidebar-header { padding: 20px 16px 12px; border-bottom: 1px solid var(--line); }
  .sidebar-header .name { font-family: Georgia, serif; font-size: 17px; font-weight: 600; }
  .sidebar-header .role { font-size: 11px; color: var(--ink-faint); margin-top: 2px; }
  .sidebar-header .stat { font-size: 11px; color: var(--accent); margin-top: 6px; font-weight: 600; }
  .sidebar-nav { flex: 1; padding: 12px 8px; display: flex; flex-direction: column; gap: 2px; }
  .sidebar-nav button {
    display: flex; align-items: center; gap: 10px; padding: 10px 12px;
    border: none; background: transparent; color: var(--ink-soft);
    font-size: 14px; cursor: pointer; border-radius: 8px; text-align: left;
    transition: all 0.12s; font-family: inherit; width: 100%;
  }
  .sidebar-nav button:hover { background: var(--bg); }
  .sidebar-nav button.active { background: var(--accent-soft); color: var(--accent); font-weight: 600; }
  .sidebar-nav .icon { font-size: 18px; width: 24px; text-align: center; }
  .sidebar-footer { padding: 12px 16px; border-top: 1px solid var(--line); font-size: 10px; color: var(--ink-faint); }

  /* MAIN */
  .main { flex: 1; padding: 24px 32px 80px; max-width: 960px; overflow-x: hidden; }
  .page { display: none; }
  .page.active { display: block; }
  .page-title { font-family: Georgia, serif; font-size: 24px; font-weight: 600; margin-bottom: 4px; }
  .page-sub { font-size: 13px; color: var(--ink-faint); margin-bottom: 24px; }

  /* CARDS */
  .card { background: var(--surface); border: 1px solid var(--line); border-radius: 10px; padding: 16px 18px; margin-bottom: 12px; }
  .card h3 { font-size: 12px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--ink-faint); margin-bottom: 8px; font-weight: 600; }

  /* PILLS */
  .pill { display: inline-block; font-size: 10px; padding: 2px 8px; border-radius: 10px; font-weight: 600; margin-right: 3px; }
  .pill-good { background: var(--good-soft); color: var(--good); }
  .pill-warn { background: var(--warn-soft); color: var(--warn); }
  .pill-bad { background: var(--bad-soft); color: var(--bad); }
  .pill-accent { background: var(--accent-soft); color: var(--accent); }

  /* STATS */
  .stat-row { display: flex; gap: 20px; flex-wrap: wrap; margin-bottom: 20px; }
  .stat-box { background: var(--surface); border: 1px solid var(--line); border-radius: 10px; padding: 14px 18px; min-width: 110px; }
  .stat-box .num { font-size: 26px; font-weight: 600; color: var(--accent); font-family: Georgia, serif; }
  .stat-box .lab { font-size: 11px; color: var(--ink-faint); }

  /* ALERTS */
  .alert { padding: 12px 16px; border-radius: 8px; font-size: 13px; margin-bottom: 12px; }
  .alert-good { background: var(--good-soft); border-left: 3px solid var(--good); color: #1b4332; }
  .alert-warn { background: var(--warn-soft); border-left: 3px solid var(--warn); color: #74420a; }
  .alert-accent { background: var(--accent-soft); border-left: 3px solid var(--accent); color: #7a3a20; }

  /* QUOTE */
  .quote { border-left: 3px solid var(--accent); padding: 8px 14px; background: var(--bg); border-radius: 0 6px 6px 0; font-size: 14px; color: var(--ink-soft); }

  /* TABLES */
  table { width: 100%; border-collapse: collapse; font-size: 13px; }
  th { text-align: left; padding: 6px 8px; border-bottom: 2px solid var(--line); font-size: 10px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--ink-faint); }
  td { padding: 8px; border-bottom: 1px solid var(--line); color: var(--ink-soft); vertical-align: top; }
  td strong { color: var(--ink); }

  /* COMPANY CARDS */
  .company-card { background: var(--surface); border: 1px solid var(--line); border-radius: 10px; padding: 16px; margin-bottom: 10px; cursor: pointer; transition: border-color 0.12s; }
  .company-card:hover { border-color: var(--accent); }
  .company-card .cc-head { display: flex; justify-content: space-between; align-items: start; margin-bottom: 6px; }
  .company-card .cc-name { font-weight: 600; font-size: 15px; }
  .company-card .cc-loc { font-size: 12px; color: var(--ink-faint); }
  .company-card .cc-why { font-size: 13px; color: var(--ink-soft); margin-top: 4px; }
  .company-card .cc-notes { margin-top: 10px; padding-top: 10px; border-top: 1px dashed var(--line); font-size: 12px; color: var(--ink-soft); display: none; }
  .company-card.expanded .cc-notes { display: block; }
  .company-card textarea { width: 100%; border: 1px solid var(--line); border-radius: 6px; padding: 8px; font-size: 12px; font-family: inherit; resize: vertical; min-height: 50px; }

  /* KANBAN */
  .kanban { display: flex; gap: 12px; overflow-x: auto; padding-bottom: 12px; min-height: 400px; }
  .kanban-col { flex: 1; min-width: 200px; background: var(--surface); border: 1px solid var(--line); border-radius: 10px; padding: 10px; }
  .kanban-col h4 { font-size: 11px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--ink-faint); margin-bottom: 8px; font-weight: 600; }
  .kanban-item { background: var(--bg); border: 1px solid var(--line); border-radius: 6px; padding: 10px; margin-bottom: 6px; cursor: grab; font-size: 12px; }
  .kanban-item:hover { border-color: var(--accent); }
  .kanban-item .ki-co { font-weight: 600; }
  .kanban-item .ki-role { color: var(--ink-faint); font-size: 11px; }
  .kanban-item.dragging { opacity: 0.5; }
  .kanban-col.drag-over { border-color: var(--accent); background: var(--accent-soft); }

  /* FORM */
  .form-row { display: flex; gap: 8px; margin-bottom: 8px; flex-wrap: wrap; }
  .form-row input, .form-row select, .form-row textarea {
    flex: 1; min-width: 120px; padding: 8px 10px; border: 1px solid var(--line);
    border-radius: 6px; font-size: 13px; font-family: inherit; background: var(--surface);
  }
  .btn { padding: 8px 16px; border: none; border-radius: 6px; font-size: 13px; cursor: pointer; font-family: inherit; font-weight: 600; }
  .btn-accent { background: var(--accent); color: white; }
  .btn-accent:hover { opacity: 0.9; }
  .btn-sm { padding: 4px 10px; font-size: 11px; }

  /* CONTACT CARDS */
  .contact-card { background: var(--surface); border: 1px solid var(--line); border-radius: 10px; padding: 14px; margin-bottom: 8px; }
  .contact-card .ct-head { display: flex; justify-content: space-between; align-items: start; }
  .contact-card .ct-name { font-weight: 600; font-size: 14px; }
  .contact-card .ct-co { font-size: 12px; color: var(--ink-faint); }
  .contact-card .ct-notes { font-size: 12px; color: var(--ink-soft); margin-top: 6px; }
  .contact-card .ct-actions { margin-top: 8px; display: flex; gap: 6px; }

  /* INTERVIEW CARDS */
  .iv-card { background: var(--surface); border: 1px solid var(--line); border-radius: 10px; margin-bottom: 8px; overflow: hidden; }
  .iv-card .iv-q { padding: 14px 18px; font-weight: 600; font-size: 14px; cursor: pointer; display: flex; justify-content: space-between; align-items: center; }
  .iv-card .iv-q .iv-arrow { color: var(--ink-faint); }
  .iv-card .iv-a { display: none; padding: 0 18px 14px; font-size: 13px; color: var(--ink-soft); border-top: 1px solid var(--line); }
  .iv-card.expanded .iv-a { display: block; padding-top: 12px; }

  /* CHECKLIST */
  .checklist-item { display: flex; align-items: center; gap: 8px; padding: 6px 0; font-size: 13px; border-bottom: 1px solid var(--line); }
  .checklist-item:last-child { border-bottom: none; }
  .checklist-item input[type="checkbox"] { width: 16px; height: 16px; cursor: pointer; }
  .checklist-item.done span { text-decoration: line-through; color: var(--ink-faint); }

  /* RESPONSIVE */
  @media (max-width: 768px) {
    body { flex-direction: column; }
    .sidebar { width: 100%; height: auto; position: relative; flex-direction: row; overflow-x: auto; }
    .sidebar-header, .sidebar-footer { display: none; }
    .sidebar-nav { flex-direction: row; }
    .main { padding: 16px; }
  }
</style>
