597|    return `<div class="contact-card">
598|      <div class="ct-head">
599|        <div><div class="ct-name">${c.name}</div><div class="ct-co">${c.co} · ${c.rel}</div></div>
600|        <div><span class="pill ${tierPill}">Tier ${c.tier}</span> <span class="pill ${statusPill}">${c.status}</span></div>
601|      </div>
602|      <div style="margin-top:10px;">
603|        <div style="font-size:11px;text-transform:uppercase;letter-spacing:0.06em;color:var(--ink-faint);margin-bottom:4px;">Objectivos da conversa</div>
604|        <div style="font-size:12px;color:var(--ink-soft);white-space:pre-line;background:var(--bg);border:1px solid var(--line);border-radius:6px;padding:8px;">${goals}</div>
605|      </div>
