608|        <textarea style="width:100%;border:1px solid var(--line);border-radius:6px;padding:8px;font-size:12px;font-family:inherit;resize:vertical;min-height:100px;background:var(--bg);" oninput="saveMsg('${msgKey}',this.value)">${msg}</textarea>
